def can_form_word(tiles: str, word: str) -> bool:
    tile_count = {}
    for tile in tiles:
        if tile in tile_count:
            tile_count[tile] += 1
        else:
            tile_count[tile] = 1

    for letter in word:
        if letter not in tile_count or tile_count[letter] == 0:
