def balancedParenthesesAndSum(expression):
    stack = []
    sum_of_digits = 0
    for char in expression:
        if char == "(":
            stack.append(char)
        elif char == ")":
            if not stack:
                return -1
            stack.pop()
        elif char.isdigit():
            sum_of_digits += int(char)
    if stack:
        return -1
    return sum_of_digits

