def longest_subarray(nums, k):
    if k == 0 or not nums:
        return 0
    count = {}
    left = 0
    max_length = 0
    for right in range(len(nums)):
        count[nums[right]] = count.get(nums[right], 0) + 1
        while len(count) > k:
            count[nums[left]] -= 1
            if count[nums[left]] == 0:
                del count[nums[left]]
            left += 1
