import pandas as pd
def get_days_of_week_from_csv(file_path):
    try:
        # Read the CSV file
        df = pd.read_csv(file_path)

        # Check if the file is not empty
        if df.empty:
            return []

        # Convert the 'Date' column to datetime format
        df['Date'] = pd.to_datetime(df['Date'])

        # Get the day of the week for each date
        day_of_week = df['Date'].dt.day_name()

        # Return the list of days of the week
        return day_of_week.tolist()
    except KeyError:
        return []

